package org.concordia.babycdf;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import com.daml.ledger.api.v2.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.io.*;
import static org.junit.jupiter.api.Assertions.*;import static org.concordia.babycdf.SourceCatalogueCodec.*;
class DemoInventoryScaleTest {
 @TempDir Path root;
 static EventOuterClass.CreatedEvent credential(long number,boolean proposal)throws Exception {Instant now=Instant.parse("2026-11-23T00:00:00Z");var o=new SourceObservation(number,proposal?SourceObservation.Kind.PROPOSAL:SourceObservation.Kind.MILESTONE,"https://github.com/"+REPOSITORY+(proposal?"/pull/":"/issues/")+number,"Unrelated title",SourceObservation.hash("body"),"open",now,now,proposal?null:184L,"",false,SourceObservation.hash("body"),false);var wire=observation(o);return EventOuterClass.CreatedEvent.newBuilder().setContractId("credential-"+number).addSignatories("opener").setCreateArguments(record("opener",ValueOuterClass.Value.newBuilder().setParty("opener").build(),"repo",text(REPOSITORY),"observation",wire,"version",integer(1),"fingerprint",text(SourceCatalogueDigest.digest(wire.getRecord())),"previousDigest",SourceOpenerLedger.none()).getRecord()).build();}
 SourceOpenerLedger adapter(List<EventOuterClass.CreatedEvent> rows)throws Exception {String pkg="a".repeat(64);var rpc=new SourceOpenerLedger.Rpc(){public Instant now(){return Instant.EPOCH;}public List<EventOuterClass.CreatedEvent> active(String m,String e){return e.equals("SourceObservationCredential")?rows:List.of();}public void submit(CommandServiceOuterClass.SubmitAndWaitRequest r){fail("inventory must not submit");}};return new SourceOpenerLedger("opener",pkg,"gov","user",rpc,new IntakeLedger("opener",pkg,pkg,"gov","user",root.toRealPath(),r->{},(p,m,e)->List.of(),false));}
 @Test void complete816BeforeScopeAndNoGenericBoundIncrease()throws Exception {
  var rows=new ArrayList<EventOuterClass.CreatedEvent>();for(long n=2000;n<2699;n++)rows.add(credential(n,true));for(long n:List.of(184L,473L,474L,475L,1028L))rows.add(credential(n,true));for(long n=3000;n<3104;n++)rows.add(credential(n,false));for(long n=538;n<=545;n++)rows.add(credential(n,false));assertEquals(816,rows.size());
  try(var ledger=adapter(rows)){assertThrows(IOException.class,()->ledger.inventory("proposal"));assertThrows(IOException.class,()->ledger.inventory("milestone"));assertEquals(List.of(184L,473L,474L,475L,1028L),ledger.demoInventory("proposal"));assertEquals(List.of(538L,539L,540L,541L,542L,543L,544L,545L),ledger.demoInventory("milestone"));}
  rows.add(rows.getFirst());try(var ledger=adapter(rows)){assertThrows(IntegrationStageFailure.class,()->ledger.demoInventory("proposal"));}
 }
 @Test void excludedMalformedAndForeignStillRejectGlobalOverflow()throws Exception {
  var rows=new ArrayList<EventOuterClass.CreatedEvent>();rows.add(credential(2000,true));rows.add(credential(3000,false));try(var ledger=adapter(rows)){assertTrue(ledger.demoInventory("proposal").isEmpty());assertTrue(ledger.demoInventory("milestone").isEmpty());}
  var good=rows.getFirst();rows.set(0,good.toBuilder().clearSignatories().addSignatories("foreign").build());try(var ledger=adapter(rows)){assertThrows(IntegrationStageFailure.class,()->ledger.demoInventory("proposal"));}
  rows.clear();for(int i=0;i<10001;i++)rows.add(good);try(var ledger=adapter(rows)){assertThrows(IOException.class,()->ledger.demoInventory("proposal"));}
 }
 @Test void staticNumbersAreCandidatesOnlyAndFixturesExist()throws Exception {for(long n:ConcordiaDemoScope.PROPOSAL_CANDIDATES)assertTrue(Files.exists(Path.of("../demo/fixtures/concordia/pr-"+n+".json")));for(long n:ConcordiaDemoScope.MILESTONE_CANDIDATES)assertTrue(Files.exists(Path.of("../demo/fixtures/concordia/issue-"+n+".json")));assertFalse(ConcordiaDemoScope.candidate("foreign/repo",SourceObservation.Kind.PROPOSAL,184));assertFalse(ConcordiaDemoScope.candidate(REPOSITORY,SourceObservation.Kind.MILESTONE,184));}
}
